def extract_singly(test_list):
    """Write a function to extract elements that occur singly in the given tuple list."""
    result = []
    seen = set()
    seen_unhashable = []
    for tup in test_list:
        for item in tup:
            try:
                if item in seen:
                    continue
                seen.add(item)
            except TypeError:
                # Unhashable element: fall back to equality comparison.
                if item in seen_unhashable or item in result:
                    continue
                seen_unhashable.append(item)
            result.append(item)
    return result
